+        clientOptions.ConfigureHttpClientBuilder?.Invoke(streamClientBuilder);
+
+        return services
+            .AddScoped<IFeature, Feature>()
+            .AddScoped<IMenuProvider, WeaverMenu>()
+            .AddScoped<IWeaverService, RemoteWeaverService>()
