+.weaver-side {
+    display: grid;
+    grid-template-rows: auto minmax(160px, 1fr) minmax(120px, 1fr) auto;
+    gap: 12px;
+}
+
+.weaver-panel {
+    padding: 12px;
+    overflow: auto;
+}
+
+.weaver-capability-grid {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: 8px;
+    margin-top: 10px;
+}
+
+.weaver-capability-pill {
+    display: flex;
+    align-items: center;
+    gap: 6px;
+    border: 1px solid var(--mud-palette-lines-default);
+    border-radius: 6px;
+    padding: 6px 8px;
+    font-size: 0.82rem;
+}
+
+.weaver-capability-pill.is-enabled {
+    color: var(--mud-palette-success);
+}
+
+.weaver-capability-pill.is-disabled {
+    color: var(--mud-palette-text-secondary);
+}
+
+.weaver-activity-list,
+.weaver-tool-list {
+    display: grid;
+    gap: 8px;
+    margin-top: 10px;
+}
+
+.weaver-activity,
+.weaver-tool,
+.weaver-proposal {
+    border: 1px solid var(--mud-palette-lines-default);
+    border-radius: 8px;
+    padding: 8px;
+}
+
+@media (max-width: 960px) {
+    .weaver-page {
+        height: auto;
+    }
+
+    .weaver-workspace {
+        grid-template-columns: 1fr;
+    }
+
+    .weaver-side {
+        grid-template-rows: none;
+    }
+
+    .weaver-message {
+        max-width: 100%;
+    }
+
+    .weaver-composer-actions {
+        align-items: stretch;
+        flex-direction: column;
+    }
+
+    .weaver-agent-select,
+    .weaver-context-kind,
+    .weaver-reference-input {
+        width: 100%;
+    }
+}
